// flatFailSource is a race-safe always-failing MetadataSource for the multi-
// worker flat-cooldown test (retrySource's unsynchronized mergeCalls counter
// races across concurrent workers). Every Merge errors -> the source exhausts
// its retry budget terminally every run.
type flatFailSource struct {
	sdk.UnsupportedSearch // the interactive search pair: unsupported (identify-match-override)
	id                    string
	merges                atomic.Int32
}

var _ sdk.MetadataSource = (*flatFailSource)(nil)

func (s *flatFailSource) Match(context.Context, *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	return &metadatav1.MatchResult{Applies: true}, nil
}
func (s *flatFailSource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (s *flatFailSource) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	md, _ := structpb.NewStruct(map[string]any{"title": "X"})
	return &metadatav1.ConvertResult{Metadata: md}, nil
}
func (s *flatFailSource) Merge(context.Context, *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	s.merges.Add(1)
	return nil, errors.New("scripted merge failure")
}

// namespacedDoc is a ready-row document carrying the tv-parser namespace with
// its provenance/view entries, a second plugin's untouched regions, and the id
// anchor the purge must never reach (enrichment D-1).
func namespacedDoc(relPath string) map[string]any {
	doc := baseDoc(relPath)
	doc["identifiers"] = map[string]any{"shikimori_id": 123.0}
	doc["sources"] = map[string]any{
		"tv-parser": map[string]any{"title": "old"},
		"tmdb":      map[string]any{"title": "other"},
	}
	doc["_provenance"] = map[string]any{
		"title": map[string]any{"plugin_id": "tv-parser"},
		"kind":  map[string]any{"plugin_id": "tmdb"},
	}
	doc["_view"] = map[string]any{
		"title": map[string]any{"value": "old", "source": "tv-parser"},
		"kind":  map[string]any{"value": "other", "source": "tmdb"},
	}
	return doc
}

// ledgerRow fetches one (item, plugin) ledger row, failing the test when absent.
func ledgerRow(t *testing.T, s *store.Store, itemID, pluginID string) store.FailureRow {
	t.Helper()
	rows, err := s.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	for _, r := range rows {
		if r.ItemID == itemID && r.PluginID == pluginID {
			return r
		}
	}
	t.Fatalf("no ledger row for (%s, %s); rows=%v", itemID, pluginID, rows)
	return store.FailureRow{}
}

// waitForLedgerAttempts polls until the (item, plugin) ledger row records at
// least wantAttempts attempts, then returns it (the async drain's terminal
// write is the arrival signal for an explicit-refresh failure).
func waitForLedgerAttempts(t *testing.T, s *store.Store, itemID, pluginID string, wantAttempts int) store.FailureRow {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		rows, err := s.ListFailures(context.Background())
		if err == nil {
			for _, r := range rows {
				if r.ItemID == itemID && r.PluginID == pluginID && r.Attempts >= wantAttempts {
					return r
				}
			}
		}
		time.Sleep(time.Millisecond)
	}
	rows, _ := s.ListFailures(context.Background())
	t.Fatalf("ledger (%s, %s) never reached attempts >= %d; rows=%v", itemID, pluginID, wantAttempts, rows)
	return store.FailureRow{}
}

// waitForLedgerAfter polls until the (item, plugin) ledger row's failed_at is
// after `after`, then returns it — the arrival signal for a specific drain.
// (The store stamps failed_at with the real clock even when the package test
// clock is fixed, so this distinguishes successive failure rounds.)
func waitForLedgerAfter(t *testing.T, s *store.Store, itemID, pluginID string, after time.Time) store.FailureRow {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		rows, err := s.ListFailures(context.Background())
		if err == nil {
			for _, r := range rows {
				if r.ItemID == itemID && r.PluginID == pluginID && r.FailedAt.After(after) {
					return r
				}
			}
		}
		time.Sleep(time.Millisecond)
	}
	rows, _ := s.ListFailures(context.Background())
	t.Fatalf("ledger (%s, %s) never recorded a failure after %v; rows=%v", itemID, pluginID, after, rows)
	return store.FailureRow{}
}

// TestReenrichSource is the explicit-refresh sweep (enrichment D-1/D-2): the
// namespace purge + re-derive joint, the bounded retry pass over lease-held
// rows, and the swept-plugin-only ledger cooldown bypass.
func TestReenrichSource(t *testing.T) {
	ctx := context.Background()

	t.Run("strip_purge_and_rederive", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_re", libID, statusReady, namespacedDoc("Show/S01E01.mkv"))
		// warm ledger rows for BOTH plugins: only the swept one may clear.
		if err := s.RecordFailure(ctx, "i_re", "tv-parser", ledgerExhausted, "boom", 3, now().Add(time.Hour)); err != nil {
			t.Fatalf("RecordFailure tv-parser: %v", err)
		}
		if err := s.RecordFailure(ctx, "i_re", "tmdb", ledgerNoData, "empty", 3, now().Add(24*time.Hour)); err != nil {
			t.Fatalf("RecordFailure tmdb: %v", err)
		}

		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
		q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()

		stripped, deferred, err := q.ReenrichSource(ctx, libID, "tv-parser")
		if err != nil {
			t.Fatalf("ReenrichSource: %v", err)
		}
		if stripped != 1 || deferred != 0 {
			t.Fatalf("stripped=%d deferred=%d, want 1/0", stripped, deferred)
		}

		it := waitForStatus(t, s, "i_re", statusReady, 2*time.Second)
		d := decodeDoc(it.Document)
		sources, _ := d["sources"].(map[string]any)
		if _, ok := sources["tv-parser"]; !ok {
			t.Fatalf("tv-parser namespace not re-derived after the strip: %v", sources)
		}
		if _, ok := sources["tmdb"]; !ok {
			t.Fatalf("tmdb namespace must survive the sweep: %v", sources)
		}
		ids, _ := d["identifiers"].(map[string]any)
		if ids["shikimori_id"] != 123.0 {
			t.Fatalf("identifiers must be untouched by the purge, got %v", ids)
		}
		prov, _ := d["_provenance"].(map[string]any)
		titleProv, _ := prov["title"].(map[string]any)
		if titleProv["plugin_id"] != "tv-parser" {
			t.Fatalf("_provenance.title must be re-derived by tv-parser, got %v", titleProv)
		}
		view, _ := d["_view"].(map[string]any)
		kindView, _ := view["kind"].(map[string]any)
		if kindView["source"] != "tmdb" {
			t.Fatalf("tmdb _view entries must survive the sweep, got %v", kindView)
		}
		// ledger: the swept plugin's cooldown cleared, the other plugin's kept.
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		tmdbKept := false
		for _, r := range rows {
			if r.ItemID == "i_re" && r.PluginID == "tv-parser" {
				t.Fatalf("swept plugin's ledger row must be cleared, got %+v", r)
			}
			if r.ItemID == "i_re" && r.PluginID == "tmdb" {
				tmdbKept = true
			}
		}
		if !tmdbKept {
			t.Fatalf("other plugin's ledger row must survive the sweep; rows=%v", rows)
		}
	})

	t.Run("held_lease_retry_pass_strips_expired_hold", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_hold", libID, statusReady, namespacedDoc("Show/S01E01.mkv"))
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		// a "worker" lease that expires just after the first pass: the bounded
		// retry pass (reenrichRetryDelay later) must lazily reclaim it and strip.
		if !q.leases.acquire("i_hold", "worker", 5*time.Millisecond) {
			t.Fatal("precondition: acquiring the hold lease failed")
		}
		stripped, deferred, err := q.ReenrichSource(ctx, libID, "tv-parser")
		if err != nil {
			t.Fatalf("ReenrichSource: %v", err)
		}
		if stripped != 1 || deferred != 0 {
			t.Fatalf("stripped=%d deferred=%d, want 1/0 (retry pass must reclaim the expired lease)", stripped, deferred)
		}
		it, err := s.GetItem(ctx, "i_hold")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		sources, _ := decodeDoc(it.Document)["sources"].(map[string]any)
		if _, ok := sources["tv-parser"]; ok {
			t.Fatalf("namespace must be gone after the retry pass stripped it: %v", sources)
		}
	})

	t.Run("live_lease_deferred_namespace_intact", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_live", libID, statusReady, namespacedDoc("Show/S01E02.mkv"))
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		if !q.leases.acquire("i_live", "worker", time.Minute) {
			t.Fatal("precondition: acquiring the live lease failed")
		}
		stripped, deferred, err := q.ReenrichSource(ctx, libID, "tv-parser")
		if err != nil {
			t.Fatalf("ReenrichSource: %v", err)
		}
		if stripped != 0 || deferred != 1 {
			t.Fatalf("stripped=%d deferred=%d, want 0/1 (a held row is counted, never silently stripped)", stripped, deferred)
		}
		it, err := s.GetItem(ctx, "i_live")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		sources, _ := decodeDoc(it.Document)["sources"].(map[string]any)
		if _, ok := sources["tv-parser"]; !ok {
			t.Fatalf("a lease-held row must keep its namespace intact: %v", sources)
		}
	})
}

// TestReenrichStatusFlip is enrichment D-3: the refresh transition flips ONLY
// the rows the sweep actually stripped to pending, untouched rows keep their
// status, and the table still rejects the illegal flips.
func TestReenrichStatusFlip(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	readyDoc := namespacedDoc("Show/S01E01.mkv")
	enrichedDoc := namespacedDoc("Show/S01E02.mkv")
	untouchedDoc := baseDoc("Show/S01E03.mkv") // carries NO tv-parser namespace: never scoped
	untouchedDoc["sources"] = map[string]any{"tmdb": map[string]any{"title": "other"}}
	putItem(t, s, "i_flip_ready", libID, statusReady, readyDoc)
	putItem(t, s, "i_flip_enriched", libID, statusEnriched, enrichedDoc)
	putItem(t, s, "i_flip_other", libID, statusReady, untouchedDoc)

	// empty resolver: the stripped rows drain to pending and STAY there (their
	// sources are unavailable, so nothing advances past pending) — the flip
	// stays observable after the drain.
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	q.resolve = mapResolver{}.resolver()
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()

	stripped, deferred, err := q.ReenrichSource(ctx, libID, "tv-parser")
	if err != nil {
		t.Fatalf("ReenrichSource: %v", err)
	}
	if stripped != 2 || deferred != 0 {
		t.Fatalf("stripped=%d deferred=%d, want 2/0", stripped, deferred)
	}

	waitForStatus(t, s, "i_flip_ready", statusPending, 2*time.Second)
	waitForStatus(t, s, "i_flip_enriched", statusPending, 2*time.Second)
	other := waitForStatus(t, s, "i_flip_other", statusReady, 2*time.Second)
	if sources, _ := decodeDoc(other.Document)["sources"].(map[string]any); len(sources) != 1 {
		t.Fatalf("untouched row's namespaces must survive verbatim, got %v", sources)
	}

	// the transition table gained exactly the two refresh rows; everything else
	// stays illegal (INV-status-owner).
	if _, err := nextState(statusReady, evRefresh); err != nil {
		t.Fatalf("ready --refresh-> pending must be legal: %v", err)
	}
	if _, err := nextState(statusEnriched, evRefresh); err != nil {
		t.Fatalf("enriched --refresh-> pending must be legal: %v", err)
	}
	for _, tc := range []struct {
		from string
		ev   enrichEvent
	}{
		{statusReady, evParsed},
		{statusReady, evBegin},
		{statusEnriched, evBegin},
		{statusPending, evRefresh},
		{statusParsed, evRefresh},
		{statusFailed, evRefresh},
	} {
		if _, err := nextState(tc.from, tc.ev); err == nil {
			t.Fatalf("nextState(%s, %s) unexpectedly succeeded; want illegal-transition error", tc.from, tc.ev)
		}
	}
}

// TestBootSweep is enrichment D-8 (the backlog's "enrichment restart sweep is
// vacuous on fresh boot"): a store holding pending items from a previous
// process, with NO scan in-process, is drained by Start alone.
func TestBootSweep(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_boot1", libID, statusPending, baseDoc("Show/S01E01.mkv"))
	putItem(t, s, "i_boot2", libID, statusPending, baseDoc("Show/S01E02.mkv"))

	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
	// NO Notify — a fresh boot: the library exists only in the store.
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()

	waitForStatus(t, s, "i_boot1", statusReady, 2*time.Second)
	waitForStatus(t, s, "i_boot2", statusReady, 2*time.Second)
}

// TestReenrichFlatCooldown is enrichment 3.4: a terminal failure of an
// explicitly-triggered run records the FLAT schedule (the pack_failed shape),
// repeated explicit failures stay flat, and automatic failures keep the
// standard doubling schedule.
func TestReenrichFlatCooldown(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC)
	withFixedClock(t, t0)
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	cfg := QueueConfig{
		MaxAttempts:   2,
		Backoff:       time.Millisecond,
		ExhaustedCool: time.Hour,       // automatic round 1
		NoDataCool:    100 * time.Hour, // the flat explicit cooldown
	}
	putItem(t, s, "i_auto", libID, statusPending, baseDoc("Show/S01E01.mkv"))
	explDoc := namespacedDoc("Show/S01E02.mkv") // pre-enriched; the explicit refresh strips it
	putItem(t, s, "i_expl", libID, statusReady, explDoc)

	fail := &flatFailSource{id: "tv-parser"}
	q := NewQueue(Deps{Store: s, Modules: reg}, cfg)
	q.resolve = mapResolver{"tv-parser": fail, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()

	// automatic failure: the standard schedule — round 1 = ExhaustedCool.
	_ = waitForStatus(t, s, "i_auto", statusReady, 2*time.Second) // tmdb settles the item
	auto := ledgerRow(t, s, "i_auto", "tv-parser")
	if auto.NextEligibleAt != t0.Add(cfg.ExhaustedCool) {
		t.Fatalf("automatic NextEligibleAt = %v, want t0+ExhaustedCool (%v) — doubling schedule unchanged",
			auto.NextEligibleAt, t0.Add(cfg.ExhaustedCool))
	}

	// explicit failure #1: flat at NoDataCool — never punished by the exhausted shape.
	if _, _, err := q.ReenrichSource(ctx, libID, "tv-parser"); err != nil {
		t.Fatalf("ReenrichSource #1: %v", err)
	}
	first := waitForLedgerAttempts(t, s, "i_expl", "tv-parser", cfg.MaxAttempts)
	if first.NextEligibleAt != t0.Add(cfg.NoDataCool) {
		t.Fatalf("explicit NextEligibleAt = %v, want t0+NoDataCool (%v) — flat schedule",
			first.NextEligibleAt, t0.Add(cfg.NoDataCool))
	}

	// explicit failure #2 (a further explicit refresh): STILL flat — no doubling
	// across explicit retries. The refresh cleared the ledger, so the retry
	// records a fresh attempt round — but at the flat NoDataCool, where the
	// standard doubling schedule would have moved to 2x ExhaustedCool.
	marker := time.Now()
	if _, _, err := q.ReenrichSource(ctx, libID, "tv-parser"); err != nil {
		t.Fatalf("ReenrichSource #2: %v", err)
	}
	second := waitForLedgerAfter(t, s, "i_expl", "tv-parser", marker)
	if second.Attempts != cfg.MaxAttempts {
		t.Fatalf("repeated explicit attempts = %d, want %d (fresh round — the refresh cleared the ledger)", second.Attempts, cfg.MaxAttempts)
	}
	if second.NextEligibleAt != t0.Add(cfg.NoDataCool) {
		t.Fatalf("repeated explicit NextEligibleAt = %v, want t0+NoDataCool again (%v) — still flat",
			second.NextEligibleAt, t0.Add(cfg.NoDataCool))
	}
}
